'use strict';
const KEY='fpl_data_v1';
const defaults=()=>({version:1,updated:new Date().toISOString(),family:{emergency:2000,target:8000,monthlyEmergency:200,monthlyIncome:1950,minReserve:300},assumptions:{stockReturn:6,bondReturn:2.5,stockVol:18,bondVol:6,correlation:0.15,inflation:2,paths:1200,seed:20261024},children:[{id:'leo',name:'Leo',initial:2800,monthly:50,years:14,stock:80,target:15000,withdrawals:0},{id:'bianca',name:'Bianca',initial:1300,monthly:50,years:17,stock:80,target:15000,withdrawals:0}]});
let state;let tab='dashboard';let selected='leo';let simCache={};let builderOwner='leo',builderTemplate='one',builderCompare='2008',compareA='',compareB='';
const $=id=>document.getElementById(id), money=x=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(x),pct=x=>(100*x).toFixed(1).replace('.',',')+'%',fmt=x=>Number(x).toLocaleString('it-IT',{maximumFractionDigits:1});
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
function valid(x){if(!x||x.version!==1||!Array.isArray(x.children)||x.children.length!==2||!x.family||!x.assumptions)throw Error('Formato backup non valido');for(const k of ['leo','bianca']){const c=x.children.find(y=>y.id===k);if(!c||x.children.filter(y=>y.id===k).length!==1||c.name!==(k==='leo'?'Leo':'Bianca')||!['initial','monthly','years','stock','target','withdrawals'].every(z=>Number.isFinite(c[z])))throw Error('Dati portafoglio non validi');if(c.withdrawals>c.initial||c.initial<0||c.monthly<0||c.years<1||c.years>40||c.stock<0||c.stock>100||c.target<0||c.withdrawals<0)throw Error('Valori portafoglio fuori intervallo')}for(const k of ['stockReturn','bondReturn','stockVol','bondVol','correlation','inflation','paths','seed'])if(!Number.isFinite(x.assumptions[k]))throw Error('Parametri non validi');if(x.assumptions.stockVol<0||x.assumptions.bondVol<0||Math.abs(x.assumptions.correlation)>1||x.assumptions.paths<100||x.assumptions.paths>10000||x.assumptions.inflation<=-99)throw Error('Parametri fuori intervallo');for(const k of ['emergency','target','monthlyEmergency','monthlyIncome','minReserve'])if(!Number.isFinite(x.family[k])||x.family[k]<0)throw Error('Dati familiari non validi');return x}
try{state=valid(JSON.parse(localStorage.getItem(KEY)))}catch(e){state=defaults()}
function save(){state.updated=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));simCache={}}
const child=id=>state.children.find(x=>x.id===id);
const ass=()=>state.assumptions;
function moments(c){const a=ass(),w=c.stock/100,mu=(w*a.stockReturn+(1-w)*a.bondReturn)/100,sigma=Math.sqrt((w*a.stockVol)**2+((1-w)*a.bondVol)**2+2*w*(1-w)*a.stockVol*a.bondVol*a.correlation)/100;return{mu,sigma}}
function rng(seed){let x=(seed>>>0)||1;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296}}
function normal(rand){return Math.sqrt(-2*Math.log(Math.max(rand(),1e-12)))*Math.cos(2*Math.PI*rand())}
function percentile(a,p){let t=(a.length-1)*p,i=Math.floor(t);return a[i]+(a[Math.min(i+1,a.length-1)]-a[i])*(t-i)}
function simulate(c){const a=ass(),key=JSON.stringify([c,a]);if(simCache[key])return simCache[key];const {mu,sigma}=moments(c),rand=rng(a.seed+(c.id==='leo'?37:79)),n=a.paths,months=Math.round(c.years*12),terminal=[],maxDD=[],yearEnd=Array.from({length:c.years+1},()=>[]);for(let i=0;i<n;i++){let value=Math.max(0,c.initial-c.withdrawals),unit=1,peak=1,dd=0;yearEnd[0].push(value);for(let m=1;m<=months;m++){const z=normal(rand);const ret=Math.exp((mu-0.5*sigma*sigma)/12+sigma/Math.sqrt(12)*z)-1;unit*=1+ret;peak=Math.max(peak,unit);dd=Math.max(dd,1-unit/peak);value=Math.max(0,value*(1+ret)+c.monthly);if(m%12===0)yearEnd[m/12].push(value)}terminal.push(value);maxDD.push(dd)}terminal.sort((a,b)=>a-b);maxDD.sort((a,b)=>a-b);const invested=Math.max(0,c.initial-c.withdrawals)+c.monthly*months;const success=terminal.filter(x=>x>=c.target).length/n;const result={terminal,median:percentile(terminal,.5),low:percentile(terminal,.05),high:percentile(terminal,.95),invested,success,ddMedian:percentile(maxDD,.5),dd95:percentile(maxDD,.95),series:yearEnd.map((v,i)=>({year:i,p05:percentile(v.sort((a,b)=>a-b),.05),p50:percentile(v,.5),p95:percentile(v,.95)}))};simCache[key]=result;return result}

function stress(c){const w=c.stock/100;return -(.45*w+.12*(1-w))}
function riskStatus(c){const f=state.family;const m=moments(c),loss=stress(c),coverage=f.target?f.emergency/f.target:1;return coverage<.5?'Attenzione liquidità':m.sigma>.15?'Rischio elevato':m.sigma>.1?'Rischio medio':'Rischio contenuto'}
function metric(label,value,detail=''){return `<article class="card"><div class="eyebrow">${label}</div><div class="metric">${value}</div>${detail?`<small>${detail}</small>`:''}</article>`}
function bar(w){return `<div class="bar"><div style="width:${w}%"></div><div style="width:${100-w}%"></div></div><div class="row"><small>Azioni ${w}%</small><small>Obbligazioni ${100-w}%</small></div>`}
function nav(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab))}
function chart(series){const W=700,H=230,p=28,max=Math.max(1,...series.map(x=>x.p95))*1.08,X=i=>p+(W-2*p)*i/(series.length-1),Y=v=>H-p-(H-2*p)*v/max;const path=(k)=>series.map((d,i)=>(i?'L':'M')+X(i).toFixed(1)+','+Y(d[k]).toFixed(1)).join(' ');const band=path('p95')+' '+series.map((d,i)=>'L'+X(series.length-1-i).toFixed(1)+','+Y(series[series.length-1-i].p05).toFixed(1)).join(' ')+' Z';return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Proiezione: fascia 5°–95° percentile e mediana"><path d="${band}" fill="#208c82" opacity=".24"/><path d="${path('p50')}" fill="none" stroke="#5ee0c6" stroke-width="3"/><path d="${path('p05')}" fill="none" stroke="#7892b9" stroke-dasharray="5 5"/><path d="${path('p95')}" fill="none" stroke="#7892b9" stroke-dasharray="5 5"/><text x="30" y="20" fill="#a4c5d2" font-size="13">${money(max/1.08)}</text><text x="30" y="${H-7}" fill="#a4c5d2" font-size="13">0</text><text x="${W-50}" y="${H-7}" fill="#a4c5d2" font-size="13">${series.length-1} anni</text></svg>`}
function dashboard(){const l=simulate(child('leo')),b=simulate(child('bianca')),f=state.family,progress=f.target?clamp(f.emergency/f.target*100,0,100):100;return `<h1>Panoramica familiare</h1><p class="lead">Capitale di partenza, PAC e rischio: contabilità separata, nessuna duplicazione con il fondo di emergenza.</p><div class="grid three">${metric('Capitale iniziale figli',money(child('leo').initial+child('bianca').initial),'Importi inseriti, non quotazioni live')}${metric('PAC totale mensile',money(child('leo').monthly+child('bianca').monthly),'Leo + Bianca')}${metric('Fondo emergenza',money(f.emergency),`${fmt(progress)}% di ${money(f.target)}`)}</div>${f.emergency<f.target?`<div class="notice">Fondo emergenza incompleto (${money(f.target-f.emergency)} mancanti). Prima di aumentare il PAC, verificare spese essenziali e riserva di liquidità.</div>`:''}<div class="grid">${state.children.map(c=>{const s=simulate(c);return `<article class="card"><div class="row"><h2>${c.name}</h2><span class="pill">${riskStatus(c)}</span></div>${bar(c.stock)}<div class="eyebrow">Capitale finale mediano simulato</div><div class="metric">${money(s.median)}</div><p>Tra ${money(s.low)} e ${money(s.high)} nel 90% centrale degli scenari simulati.</p><div class="row"><span>Probabilità obiettivo</span><strong>${pct(s.success)}</strong></div><button class="btn" data-action="select" data-id="${c.id}">Apri ${c.name}</button></article>`}).join('')}</div><div class="card"><h2>Come leggere i risultati</h2><p>Le stime derivano da rendimenti e volatilità ipotizzati, con simulazioni mensili lognormali. La probabilità stimata non è una garanzia né una previsione verificata su dati di mercato.</p></div>`}
function field(label,id,value,min,max,step='1'){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${value}"></div>`}
function portfolio(){return `<h1>Portafogli separati</h1><p class="lead">Valori contabili inseriti manualmente. I capitali iniziali non sono necessariamente già investiti.</p><div class="flex">${state.children.map(c=>`<button class="btn ${selected===c.id?'primary':''}" data-action="select" data-id="${c.id}">${c.name}</button>`).join('')}</div>${(()=>{const c=child(selected),s=simulate(c);return `<div class="grid"><section class="card"><h2>Parametri di ${c.name}</h2>${field('Capitale iniziale (€)','initial',c.initial,0,100000000)}${field('PAC mensile (€)','monthly',c.monthly,0,1000000)}${field('Anni residui','years',c.years,1,40)}${field('Quota azionaria (%)','stock',c.stock,0,100,5)}${field('Obiettivo nominale (€)','target',c.target,0,100000000)}${field('Prelievi già effettuati dal capitale iniziale (€)','withdrawals',c.withdrawals,0,100000000)}<button class="btn primary" data-action="savechild">Salva portafoglio</button></section><section class="card"><h2>Proiezione di ${c.name}</h2>${bar(c.stock)}${metric('Mediana finale',money(s.median))}<div class="row"><span>Versamenti netti</span><strong>${money(s.invested)}</strong></div><div class="row"><span>5° percentile</span><strong>${money(s.low)}</strong></div><div class="row"><span>95° percentile</span><strong>${money(s.high)}</strong></div><div class="row"><span>Probabilità obiettivo</span><strong>${pct(s.success)}</strong></div><p class="help">Il capitale iniziale è assunto disponibile per investire subito. I prelievi riducono quel capitale. Non è un registro di quote o movimenti di broker.</p></section></div><div class="card"><h2>Distribuzione del capitale nel tempo</h2>${chart(s.series)}<p class="help">Linea centrale = mediana; fascia = 5°–95° percentile. Valori nominali prima di imposte e commissioni.</p></div>`})()}`}
function risk(){const c=child(selected),s=simulate(c),m=moments(c),a=ass(),oneVaR=1-Math.exp(m.mu-.5*m.sigma*m.sigma-1.645*m.sigma),oneES=1-Math.exp(m.mu-.5*m.sigma*m.sigma+.5*m.sigma*m.sigma)*((erf(((-1.645)-m.sigma)/Math.sqrt(2))+1)/2)/.05;return `<h1>Risk Manager</h1><p class="lead">Misure modellistiche sul rendimento annuo del portafoglio, non limiti certi di perdita.</p><div class="flex">${state.children.map(x=>`<button class="btn ${selected===x.id?'primary':''}" data-action="select" data-id="${x.id}">${x.name}</button>`).join('')}</div><div class="grid three">${metric('Volatilità annua',pct(m.sigma),'Da pesi e correlazione ipotizzati')}${metric('VaR annuo 95%',pct(Math.max(0,oneVaR)),'Perdita-soglia modellistica')}${metric('Stress -45% azioni',pct(stress(c)),'Obbligazioni -12% simultaneamente')}${metric('Drawdown mediano simulato',pct(s.ddMedian),'Massimo lungo tutto il percorso')}${metric('Drawdown 95° percentile',pct(s.dd95),'Non è il peggior caso possibile')}${metric('Probabilità obiettivo',pct(s.success),`${money(c.target)} nominali tra ${c.years} anni`)}</div><div class="card"><h2>Controlli di rischio</h2><p><strong>Risk capacity familiare:</strong> fondo emergenza ${money(state.family.emergency)} / ${money(state.family.target)}. Non deduciamo la capacità di perdita dalla sola età dei figli.</p><p><strong>Perdita stress su capitale iniziale netto:</strong> ${money(Math.max(0,c.initial-c.withdrawals)*Math.abs(stress(c)))}. Lo stress è uno scenario ipotetico, non un VaR.</p><p><strong>Rischio di obiettivo:</strong> ${pct(1-s.success)} di simulazioni sotto ${money(c.target)} alla scadenza. Non include fiscalità e inflazione.</p><div class="notice">Il portafoglio non è ottimizzato automaticamente: prima di una proposta definitiva servono spese essenziali, data effettiva dell'obiettivo e massima perdita sostenibile.</div></div><div class="card"><h2>Confronto delle allocazioni</h2><table><thead><tr><th>Azioni</th><th>Volatilità</th><th>Mediana</th><th>Obiettivo</th></tr></thead><tbody>${[0,40,60,70,80,100].map(w=>{const x={...c,stock:w},v=simulate(x),mm=moments(x);return `<tr><td>${w}%</td><td>${pct(mm.sigma)}</td><td>${money(v.median)}</td><td>${pct(v.success)}</td></tr>`}).join('')}</tbody></table><p class="help">Portafogli con medesimi capitale, PAC e durata. Il confronto non identifica automaticamente un vincitore.</p></div>`}
function erf(x){const sign=x<0?-1:1;x=Math.abs(x);const t=1/(1+.3275911*x);return sign*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-x*x))}
// SCENARI DIDATTICI: rendimenti IPOTETICI ispirati alle crisi, non serie storiche osservate.
const CRISES=[
{id:'1929',label:'1929 · Grande Depressione',description:'Scenario estremo di crisi pluriennale, non backtest del 1929.',stocks:[-.38,-.29,-.25,.25,.20],bonds:[.04,.02,.03,.02,.02]},
{id:'1973',label:'1973–74 · Petrolio e inflazione',description:'Scenario di inflazione elevata e due anni negativi.',stocks:[-.20,-.28,.30,.08],bonds:[-.08,-.06,.03,.04]},
{id:'1987',label:'1987 · Lunedì nero',description:'Scenario di shock rapido concentrato in un anno.',stocks:[-.28,.18,.12],bonds:[.04,.03,.03]},
{id:'2000',label:'2000–02 · Bolla dot-com',description:'Scenario di tre anni azionari negativi.',stocks:[-.12,-.20,-.26,.20,.12],bonds:[.06,.05,.04,.03,.03]},
{id:'2008',label:'2008–09 · Crisi finanziaria',description:'Scenario di forte crollo e recupero successivo.',stocks:[-.45,.28,.12,.08],bonds:[.05,.02,.03,.03]},
{id:'2020',label:'2020 · Pandemia',description:'Scenario di shock improvviso; i dati annuali non mostrano il minimo infrannuale.',stocks:[-.34,.40,.10],bonds:[.02,.01,.02]},
{id:'2022',label:'2022 · Inflazione e tassi',description:'Scenario di ribasso simultaneo di azioni e obbligazioni.',stocks:[-.22,.16,.09],bonds:[-.14,.05,.03]}
];
let crisisId='2008',crisisYear=1;
function scenario(c,crisis,first,keepPAC=true){
 const w=c.stock/100,base=(Math.max(0,c.initial-c.withdrawals)),rows=[{year:0,value:base,paid:base,unit:100,return:0}],mu=moments(c).mu;
 let value=base,paid=base,unit=100,peak=100,maxDD=0,lowest=base,lowYear=0,recovered=null,precrisisPeak=null;
 for(let y=1;y<=Math.round(c.years);y++){
   const offset=y-first,active=offset>=0&&offset<crisis.stocks.length;
   const r=active?w*crisis.stocks[offset]+(1-w)*crisis.bonds[offset]:mu;
   if(y===first)precrisisPeak=unit;
   const monthly=(1+r)>0?Math.pow(1+r,1/12)-1:-1;
   for(let m=0;m<12;m++){
     unit*=1+monthly;peak=Math.max(peak,unit);maxDD=Math.max(maxDD,1-unit/peak);
     const contribution=(keepPAC||y<first||y>=first+crisis.stocks.length)?c.monthly:0;
     value=value*(1+monthly)+contribution;paid+=contribution;
   }
   if(value<lowest){lowest=value;lowYear=y}
   if(precrisisPeak!==null&&y>=first&&recovered===null&&unit>=precrisisPeak&&y>first)recovered=y;
   rows.push({year:y,value,paid,unit,return:r,crisis:active});
 }
 return{rows,maxDD,lowest,lowYear,recovered,final:value,paid};
}
function historical(){const c=child(selected),cr=CRISES.find(x=>x.id===crisisId)||CRISES[4];crisisYear=clamp(crisisYear,1,c.years);const x=scenario(c,cr,crisisYear,true),paused=scenario(c,cr,crisisYear,false),normal=scenario(c,{stocks:[],bonds:[]},crisisYear,true);const first=x.rows[crisisYear-1];const worst=x.rows.filter(r=>r.crisis).reduce((m,r)=>r.value<m.value?r:m,{value:Infinity});const finalReal=x.final/Math.pow(1+ass().inflation/100,c.years);return `<h1>Crisi storiche · Stress test</h1><p class="lead">Come reagirebbe il portafoglio di ${c.name} a shock ipotetici ispirati alle crisi più note?</p><div class="notice">⚠️ <strong>NON È UN BACKTEST STORICO.</strong> I rendimenti di crisi sono ipotesi illustrative, non quotazioni storiche verificate né risultati di VWCE. Fuori dalla crisi si applica il rendimento atteso configurato. Il recupero è calcolato sull'indice senza PAC; i valori finali includono il PAC.</div><div class="flex">${state.children.map(z=>`<button class="btn ${selected===z.id?'primary':''}" data-action="select" data-id="${z.id}">${z.name}</button>`).join('')}</div><div class="grid"><section class="card"><h2>Scenario</h2><label for="crisisSelect">Crisi di riferimento</label><select id="crisisSelect">${CRISES.map(z=>`<option value="${z.id}" ${z.id===cr.id?'selected':''}>${z.label}</option>`).join('')}</select><label class="field" for="crisisYear">Inizio crisi nell'anno del piano (1–${c.years})</label><input id="crisisYear" type="number" min="1" max="${c.years}" value="${crisisYear}"><p class="help">${cr.description} La crisi può proseguire oltre l'orizzonte: in tal caso viene troncata.</p><p class="help">Allocazione fissa ${c.stock}% azioni / ${100-c.stock}% obbligazioni; PAC ${money(c.monthly)} mensile a fine mese.</p></section><section class="card"><h2>Risultati dello scenario</h2><div class="grid"><div>${metric('Drawdown massimo',pct(x.maxDD),'Indice senza flussi di cassa')}</div><div>${metric('Capitale finale',money(x.final),'Nominale, con PAC')}</div><div>${metric('Capitale finale reale',money(finalReal),'Euro di oggi, inflazione ipotizzata')}</div><div>${metric('Versamenti totali',money(x.paid),'Capitale iniziale netto incluso')}</div></div><p class="help">${x.recovered===null?'Recupero del livello pre-crisi: non osservato entro l’orizzonte.':`Recupero dell’indice pre-crisi entro l’anno ${x.recovered}.`} Valutazione solo su chiusure annuali; i minimi infrannuali non sono rilevati.</p></section></div><div class="grid three">${metric('Con PAC costante',money(x.final),'Scenario selezionato')}${metric('PAC sospeso nella crisi',money(paused.final),'Solo durante gli anni di shock')}${metric('Senza crisi',money(normal.final),'Ipotesi di rendimento medio costante')}</div><section class="card"><h2>Confronto anno per anno</h2><div class="table-scroll"><table><thead><tr><th>Anno</th><th>Rendimento</th><th>Capitale con PAC</th><th>Versato cumulato</th><th>Indice (100 iniziale)</th><th>Fase</th></tr></thead><tbody>${x.rows.map(r=>`<tr class="${r.crisis?'crisis-row':''}"><td>${r.year}</td><td>${r.year?(r.return>=0?'+':'')+fmt(r.return*100)+'%':'—'}</td><td>${money(r.value)}</td><td>${money(r.paid)}</td><td>${fmt(r.unit)}</td><td>${r.crisis?'Crisi':r.year?'Base':'Inizio'}</td></tr>`).join('')}</tbody></table></div><p class="help">Rendimento: combinazione annuale ipotetica azioni/obbligazioni, ribilanciata. L'indice è separato dai versamenti: misura correttamente il drawdown del mercato simulato.</p></section><section class="card"><h2>Resistere alla perdita: verifica familiare</h2><p>Fondo emergenza: <strong>${money(state.family.emergency)}</strong> su ${money(state.family.target)} (${fmt(state.family.target?100*state.family.emergency/state.family.target:100)}%).</p><p>Uno stress test non dimostra che la famiglia riuscirebbe a mantenere l'investimento: servono disponibilità liquide, spese essenziali e capacità di non vendere durante la crisi.</p><p class="help">Costi ETF, imposte, spread, variazioni di cambio e sequenze di rendimenti infrannuali non sono inclusi. Nessuna probabilità statistica è associata a questi scenari.</p></section>`}

