 balanced:{name:'Bilanciato 60/40',holdings:[{isin:'IE00BK5BQT80',name:'VWCE',asset:'stock',weight:60},{isin:'IE00BDBRDM35',name:'AGGH',asset:'bond',weight:40}]},
 butterfly:{name:'Golden Butterfly · proxy semplificato',holdings:[{isin:'',name:'Azioni large cap',asset:'stock',weight:20},{isin:'',name:'Azioni small cap value',asset:'stock',weight:20},{isin:'',name:'Titoli di Stato lunghi',asset:'bond',weight:20},{isin:'',name:'Titoli di Stato brevi',asset:'bond',weight:20},{isin:'',name:'Oro (ETC)',asset:'gold',weight:20}]},
