function esc(v){return String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function checkIsin(code){code=code.toUpperCase().replace(/\s/g,'');if(!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(code))return false;const digits=[...code].map(ch=>/[A-Z]/.test(ch)?String(ch.charCodeAt(0)-55):ch).join('');let sum=0,twice=false;for(let i=digits.length-1;i>=0;i--){let d=Number(digits[i]);if(twice){d*=2;if(d>9)d-=9}sum+=d;twice=!twice}return sum%10===0}
function validHoldings(h){if(!Array.isArray(h)||!h.length||h.length>20)throw Error('Servono da 1 a 20 strumenti');let total=0;for(const x of h){if(!['stock','bond','gold','cash'].includes(x.asset)||!Number.isFinite(x.weight)||x.weight<=0||x.weight>100||typeof x.name!=='string'||!x.name.trim()||x.name.length>100||typeof x.isin!=='string'||(x.isin&&!checkIsin(x.isin)))throw Error('Strumento o ISIN non valido');total+=x.weight}if(Math.abs(total-100)>.001)throw Error('La somma dei pesi deve essere 100%');return h}
function portfolios(){if(!Array.isArray(state.portfolios))state.portfolios=[];return state.portfolios}
function modelReturns(cr,y){const k=y;return {stock:cr.stocks[k]??ass().stockReturn/100,bond:cr.bonds[k]??ass().bondReturn/100,gold:cr.gold?.[k]??.03,cash:0}}
function runPortfolio(c,h,cr){const years=Math.round(c.years);let val=Math.max(0,c.initial-c.withdrawals),paid=val,unit=100,peak=100,dd=0,rec=null,low=val;const rows=[{year:0,value:val,unit,paid,return:0}];for(let y=1;y<=years;y++){const rr=modelReturns(cr,y-1),r=h.reduce((sum,z)=>sum+z.weight/100*rr[z.asset],0),mr=Math.pow(Math.max(.00001,1+r),1/12)-1;for(let m=0;m<12;m++){unit*=1+mr;peak=Math.max(peak,unit);dd=Math.max(dd,1-unit/peak);val=val*(1+mr)+c.monthly;paid+=c.monthly}low=Math.min(low,val);if(y>1&&rec===null&&unit>=100)rec=y;rows.push({year:y,value:val,unit,paid,return:r})}return{rows,final:val,paid,dd,low,recovered:rec}}

// v1.4 Historical Risk Engine. Historical returns must be provided by the user as sourced CSV.
// No synthetic or illustrative series are ever labelled historical.
let historicalAvailableAssets=[], historicalDataset=null, historicalDataStatus='Caricamento archivio automatico…', historicalA='', historicalB='', historicalOwner='leo', historicalWindow='2008',historicalMetadata=null,historicalMode='single',historicalSingle='';
const HIST_WINDOWS={dotcom:['2000-01','2002-12','2000–2002 · Dot-com'],crisis2008:['2007-10','2009-03','2007–2009 · Crisi finanziaria'],covid:['2020-02','2020-04','2020 · Covid'],rates:['2022-01','2022-12','2022 · Inflazione e tassi'],all:[null,null,'Intero dataset']};
const HIST_ASSETS=['stock','bond','gold','cash'];
function parseHistoryCSV(raw){
 const lines=raw.replace(/^\uFEFF/,'').trim().split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.startsWith('#'));
 if(lines.length<13)throw Error('Servono almeno 12 mesi consecutivi di rendimenti più intestazione');
 const sep=lines[0].includes(';')?';':',';
 const hdr=lines[0].split(sep).map(x=>x.trim().toLowerCase());
 if(hdr.join('|')!=='date|stock|bond|gold|cash')throw Error('Intestazione richiesta: date,stock,bond,gold,cash (oppure separatore ;)');
 if(lines.length>1501)throw Error('Massimo 1500 osservazioni mensili');
 let prev=null;
 const data=lines.slice(1).map((line,i)=>{
  const a=line.split(sep).map(x=>x.trim());
  if(a.length!==5||!/^(19|20|21)\d\d-(0[1-9]|1[0-2])$/.test(a[0]))throw Error('Data o colonne non valide alla riga '+(i+2));
  const dt=Number(a[0].slice(0,4))*12+Number(a[0].slice(5,7));
  if(prev!==null&&dt!==prev+1)throw Error('Mese mancante, ripetuto o fuori ordine: '+a[0]);prev=dt;
  const out={date:a[0]};
  HIST_ASSETS.forEach((k,j)=>{const v=Number(a[j+1].replace('%','').replace(',','.'));if(!Number.isFinite(v)||v<=-100||v>1000)throw Error('Rendimento non valido in '+a[0]+' / '+k);out[k]=v/100});
  return out;
 });
 return data;
}
function portfolioMonthlyReturn(h,row){return h.reduce((sum,z)=>sum+z.weight/100*row[z.asset],0)}
function historyRisk(h,data,c){
 const base=Math.max(0,c.initial-c.withdrawals);let unit=100,peak=100,peakAt=null,troughAt=null,dd=0,recAt=null,underwater=false,firstPeakDate=null,wealth=base,paid=base;
 let worst=Infinity,win=0,negative=0,sum=0,lowestWealth=wealth;
 const rows=[{date:'Inizio',unit,wealth,paid,ret:0}];
 for(const r of data){const ret=portfolioMonthlyReturn(h,r);if(ret<worst)worst=ret;if(ret<0)negative++;sum+=ret;
  unit*=1+ret;wealth=wealth*(1+ret)+c.monthly;paid+=c.monthly;lowestWealth=Math.min(lowestWealth,wealth);
  if(unit>peak){peak=unit;peakAt=r.date;if(underwater&&recAt===null)recAt=r.date;underwater=false}
  else if(unit<peak){underwater=true;const depth=1-unit/peak;if(depth>dd){dd=depth;troughAt=r.date;firstPeakDate=peakAt||'Inizio'}}
  rows.push({date:r.date,unit,wealth,paid,ret});win++;
 }
 const compound=unit/100-1;return{rows,dd,firstPeakDate,troughAt,recAt,compound,avg:sum/win,worst,negative,final:wealth,paid,lowestWealth,months:win};
}
async function loadHistoricalArchive(){
 try{
  const response=await fetch('/historical-data.json',{cache:'no-store'});
  if(!response.ok)throw Error('Archivio non pubblicato (HTTP '+response.status+')');
  const obj=await response.json();
  if(!obj||obj.status!=='ready'||!Array.isArray(obj.rows)||!obj.source||!obj.methodology||obj.currency!=='EUR')throw Error('Archivio storico verificato non ancora disponibile');
  if(obj.rows.length<12||obj.rows.length>1500)throw Error('Copertura insufficiente');
  const available=Array.isArray(obj.available_assets)?obj.available_assets:HIST_ASSETS;
  if(!available.length||available.some(k=>!HIST_ASSETS.includes(k))||new Set(available).size!==available.length)throw Error('Classi di attività non valide');
  let previous=null;
  for(const r of obj.rows){
   if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(r.date))throw Error('Data non valida');
   const month=Number(r.date.slice(0,4))*12+Number(r.date.slice(5));
   if(previous!==null&&month!==previous+1)throw Error('Serie con mesi mancanti');
   previous=month;
   for(const key of available)if(typeof r[key]!=='number'||!Number.isFinite(r[key])||r[key]<=-1||r[key]>10)throw Error('Rendimento non valido: '+key);
  }
  if(!obj.provider_url||!/^https:\/\//.test(obj.provider_url)||!obj.as_of||!/^\d{4}-\d{2}-\d{2}$/.test(obj.as_of)||!obj.asset_sources||available.some(k=>typeof obj.asset_sources[k]!=='string'||obj.asset_sources[k].length<8))throw Error('Metadati della fonte incompleti');
  historicalAvailableAssets=available;
  historicalDataset={source:obj.source+' · '+obj.methodology,rows:obj.rows};
  historicalMetadata={provider_url:obj.provider_url,as_of:obj.as_of,asset_sources:obj.asset_sources};
  historicalDataStatus='Archivio automatico caricato e validato ('+obj.rows.length+' mesi)';
 }catch(e){historicalDataStatus=e.message}
 if(tab==='historyengine')render();
}
// Single-portfolio historical analysis: uses the same verified monthly archive as comparison.
// Drawdown recovery is tracked from the specific pre-trough peak, not from an arbitrary prior recovery.
function singleHistoryStats(holdings,data,c){
 const base=Math.max(0,c.initial-c.withdrawals);let unit=100,peak=100,peakDate='Inizio',maxDD=0,trough=null,ddPeak=null,ddPeakValue=100;
 let wealth=base,paid=base,worst=Infinity,negative=0,sum=0;
 const rows=[{date:'Inizio',unit,wealth,paid,ret:0}];
 for(const r of data){
  const ret=portfolioMonthlyReturn(holdings,r);
  if(!Number.isFinite(ret)||ret<=-1)throw Error('Rendimento portafoglio non valido: '+r.date);
  worst=Math.min(worst,ret);if(ret<0)negative++;sum+=ret;
  unit*=1+ret;wealth=wealth*(1+ret)+c.monthly;paid+=c.monthly;
  if(unit>peak){peak=unit;peakDate=r.date}
  const dd=1-unit/peak;
  if(dd>maxDD){maxDD=dd;trough=r.date;ddPeak=peakDate;ddPeakValue=peak}
  rows.push({date:r.date,unit,wealth,paid,ret});
 }
 const troughIndex=rows.findIndex(r=>r.date===trough);
 const recovery=troughIndex<0?null:rows.slice(troughIndex+1).find(r=>r.unit>=ddPeakValue)?.date||null;
 const recoveryMonths=recovery?((+recovery.slice(0,4)-(+trough.slice(0,4)))*12+(+recovery.slice(5)-(+trough.slice(5)))):null;
 return {rows,dd:maxDD,trough,peak:ddPeak,recovery,recoveryMonths,worst,negative,avg:sum/data.length,compound:unit/100-1,final:wealth,paid,months:data.length};
}
